<?php declare(strict_types=1);
require dirname(__DIR__,2).'/native/bootstrap.php';
use Kulturhus\Native\{TestSupport,Shared\Access,Shared\Db,Communication\VideoReuseRequests};
$c=TestSupport::config();if(PHP_SAPI!=='cli'||getenv('KH_NATIVE_CI')!=='1'||($c['owner']??'')!=='isolated-native-ci'||($c['label']??'')!=='native-video-reuse-requests')exit(1);$input=json_decode(stream_get_contents(STDIN),true,16,JSON_THROW_ON_ERROR);$db=TestSupport::db();$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/video-reuse-runtime';$source=Db::run($db,'SELECT source_id FROM native_social_videos WHERE club_id=? AND id=?',[(new Access($db,'admin'))->club(),$input['video']])->fetchColumn();$f=fopen($root.'/worker-ready','x');if(!$f)throw new RuntimeException('Owned new readiness signal required.');chmod($root.'/worker-ready',0600);fwrite($f,'ready');fclose($f);$result=(new VideoReuseRequests($db,new Access($db,'admin'),$root.'/media'))->save($input['item'],$input['video'],$source,1,0);echo json_encode($result,JSON_THROW_ON_ERROR).PHP_EOL;
